{"nbformat":4,"nbformat_minor":0,"metadata":{"colab":{"provenance":[],"authorship_tag":"ABX9TyOgwYfgx8Zp7VYYdtDuBFrn"},"kernelspec":{"name":"python3","display_name":"Python 3"},"language_info":{"name":"python"}},"cells":[{"cell_type":"code","source":["\n","import random\n","import string\n","\n","def generate_password(length, use_upper, use_lower, use_digits, use_symbols):\n","    characters = \"\"\n","\n","    if use_upper:\n","        characters += string.ascii_uppercase\n","    if use_lower:\n","        characters += string.ascii_lowercase\n","    if use_digits:\n","        characters += string.digits\n","    if use_symbols:\n","        characters += string.punctuation\n","\n","    if not characters:\n","        return None\n","\n","    password = \"\".join(random.choice(characters) for _ in range(length))\n","    return password\n","\n","\n","def main():\n","    print(\"========== PASSWORD GENERATOR ==========\")\n","\n","    try:\n","        length = int(input(\"Enter password length: \"))\n","        if length <= 0:\n","            print(\"Password length must be greater than 0.\")\n","            return\n","    except ValueError:\n","        print(\"Invalid input! Please enter a number.\")\n","        return\n","\n","    use_upper = input(\"Include uppercase letters? (y/n): \").lower() == \"y\"\n","    use_lower = input(\"Include lowercase letters? (y/n): \").lower() == \"y\"\n","    use_digits = input(\"Include numbers? (y/n): \").lower() == \"y\"\n","    use_symbols = input(\"Include special characters? (y/n): \").lower() == \"y\"\n","\n","    password = generate_password(\n","        length,\n","        use_upper,\n","        use_lower,\n","        use_digits,\n","        use_symbols\n","    )\n","\n","    if password is None:\n","        print(\"Error: Please select at least one character type.\")\n","    else:\n","        print(\"\\nGenerated Password:\", password)\n","\n","\n","if __name__ == \"__main__\":\n","    main()"],"metadata":{"colab":{"base_uri":"https://localhost:8080/"},"id":"R-EyoKEkqqlb","outputId":"11c2d249-21e4-44aa-f0fe-2bfd16f5d0a6"},"execution_count":null,"outputs":[{"metadata":{"tags":null},"name":"stdout","output_type":"stream","text":["========== PASSWORD GENERATOR ==========\n"]}]}]}